/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('offers')` (or `ctx.tryUse` for an optional dependency). */
export interface OffersPublicApi {
  /** Current offer with terms and status Used by: cart, checkout, orders, promotions, advertising, wishlist, search, graphql. */
  getOffer(offerId: string): Promise<Offer | null>;
  /** Price, availability, delivery estimate and comparable total for one offer at a location Used by: cart, checkout, graphql. */
  quoteOffer(offerId: string, quantity: number, postalCode?: string): Promise<OfferView>;
  /** Scenario 2: reports price, stock, delivery or terms changes since the cart line was added. Never substitutes another seller. Used by: cart, checkout. */
  revalidate(lines: { offerId: string, quantity: number, termsVersion: number, price: common.Money }[], postalCode: string): Promise<{ ok: boolean, changes: OfferChange[] }>;
  /** Frozen seller, condition, notes, missing items, price, compare-at and terms stored on the order item (plan ch. 8) Used by: orders. */
  snapshotForOrder(offerId: string): Promise<OfferSnapshot>;
  /** Featured offer under the published rule; null when no eligible offer Used by: search, wishlist, content, advertising. */
  getFeaturedOffer(variantId: string, postalCode?: string): Promise<OfferView | null>;
  /** Active offers for indexing (from price, sellers, conditions, delivery flags) Used by: search, promotions. */
  listActiveOffersForProduct(productId: string): Promise<OfferSummary[]>;
  /** Active, in stock and featured-eligible. Sponsored products may only promote such offers (plan ch. 16). Used by: advertising. */
  isPromotable(offerId: string): Promise<boolean>;
  /** Lowest offer price in force in the window, from offer_price_history. The single source for honest was-prices. Used by: promotions, wishlist. */
  lowestPrice(offerId: string, sinceDays: number, before?: string): Promise<common.Money | null>;
  /** Lowest, highest and current price in force in the window, from offer_price_history (wishlist price hints). Used by: wishlist. */
  priceRange(offerId: string, sinceDays: number): Promise<{ lowest: common.Money, highest: common.Money, current: common.Money, unchanged: boolean } | null>;
  /** All offers for a product variant with comparable totals to a delivery location (all-offers page). Same as GET /products/{productId}/offers; primes the quoteOffer loader. Used by: graphql. */
  compareOffers(productId: string, opts: { variantId?: string, condition?: 'all'|'new'|'used'|'refurbished', postalCode?: string, sort?: 'total_cost'|'fastest_delivery' }): Promise<OfferComparison>;
  /** Featured offer per product (default variant when variantId is omitted) under the published rule, batched for product cards and the purchase box Used by: graphql. */
  getFeaturedOfferForProduct(items: { productId: string, variantId?: string }[], postalCode?: string): Promise<Record<string, Offer | null>>;
  /** Active offer count and price range per product; the lowest price always names its eligible offer Used by: graphql. */
  getOfferStats(productIds: string[], opts?: { condition?: 'all'|'new'|'used'|'refurbished' }): Promise<Record<string, { count: number, lowest: common.Money, highest: common.Money, lowestOfferId: string, lowestSellerName: string } | null>>;
  /** Variant chooser cues: offer count, lowest price, in stock, summary label Used by: graphql. */
  getVariantOfferSummaries(variantIds: string[], postalCode?: string): Promise<Record<string, VariantAvailability>>;
  /** The seller's own offers on each product, any status (Seller Center product detail) Used by: graphql, catalog. */
  listOwnOffersForProduct(sellerId: string, productIds: string[]): Promise<Record<string, Offer[]>>;
  /** One of the seller's own offers; null for another seller's offer Used by: graphql. */
  getOwnOffer(sellerId: string, offerId: string): Promise<Offer | null>;
  /** Own offers matching title, seller SKU or GTIN, for the Seller Center top-bar search Used by: search. */
  searchOwnOffers(sellerId: string, q: string, limit: number): Promise<{ items: OfferSummary[], more: boolean }>;
  /** Any offer with status reason, eligibility, price history, status log and price changes (staff) Used by: graphql. */
  getOfferAdmin(offerId: string): Promise<Offer | null>;
  /** All offers with filters, including featured-ineligible offers by reason (staff) Used by: graphql, search, catalog. */
  listOffersAdmin(filter: { sellerId?: string, official?: boolean, productId?: string, status?: string[], featuredEligible?: boolean, ineligibilityCode?: string, q?: string }, page: common.PageInput): Promise<common.Page<Offer>>;
  /** Why each offer is or is not featured for a variant and location (staff) Used by: graphql. */
  getFeaturedDecision(productId: string, variantId?: string, postalCode?: string): Promise<FeaturedDecision>;
  /** The offer for the purchase box: the requested offer when it is active on the product, otherwise the featured offer for the variant and location (ProductPage with a nullable offer id) Used by: graphql. */
  getPurchaseBoxOffer(items: { productId: string, offerId?: string, variantId?: string }[], postalCode?: string): Promise<Record<string, Offer | null>>;
  /** Active offers for a list of ids in the given order, inactive ones left out (storefront featured collections) Used by: sellers, graphql. */
  listActiveOffersByIds(offerIds: string[], limit?: number): Promise<Offer[]>;
  /** Batch read by id in any status (draft, removed and ineligible included), with sellerId (null for the Official Store: callers that need a seller id use OFFICIAL_STORE_ID) and title. Unknown ids map to null. Replaces per-line getOffer loops in cart revalidation, promotions evaluation and advertising checks. catalog.refresh-counts fills offer_index prices it does not have yet. Used by: cart, promotions, advertising, catalog. */
  getOffers(offerIds: string[]): Promise<Record<string, Offer | null>>;
  /** Offers that still use a shipping profile: every status except removed (drafts and paused offers count, because they can be published again). One count query on (shipping_profile_id, status); shipping refuses to delete or deactivate a profile in use (PROFILE_IN_USE) without paging through listOffersAdmin. Used by: shipping. */
  countActiveOffersByProfile(shippingProfileId: string): Promise<number>;
  /** Export rows for reports datasets offers.admin.offers and offers.seller.offers (seller rows scoped to the principal's seller) Used by: reports. */
  exportRows(dataset: string, filters: unknown, principal: identity.Principal, cursor?: string): Promise<{ rows: unknown[], nextCursor?: string }>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`offers.<table>`, ctx.mongo.table(name)). */
export interface OffersDb {
  /** One row per offer; product and seller are referenced by id only */
  offers: {
    id: string;
    owner_type: 'official' | 'seller';
    seller_id: string | null;
    product_id: string;
    variant_id: string;
    /** product title with variant label, denormalised from catalog for title search */
    title: string;
    condition: string;
    condition_notes: string | null;
    included_items: Json;
    missing_items: Json;
    /** product box changed since missingItems was saved */
    missing_items_stale: boolean;
    seller_sku: string;
    stock_item_id: string;
    price_amount: number;
    currency: string;
    compare_at_amount: number | null;
    compare_at_basis: string | null;
    compare_at_verified: boolean;
    sale_ends_at: Date | null;
    purchase_limit: number | null;
    dispatch_business_days: number;
    same_day_cutoff: string | null;
    ships_from: string;
    shipping_profile_id: string;
    fulfilled_by: 'official_warehouse' | 'seller' | 'marketly_service';
    return_kind: string;
    return_window_days: number;
    free_return_shipping: boolean;
    /** returns EffectiveTerms.policyVersion at save */
    return_policy_version: string | null;
    /** returns category exception summary at save */
    return_category_exception: string | null;
    warranty_kind: string;
    warranty_months: number | null;
    warranty_handled_by: string | null;
    status: 'draft' | 'active' | 'paused' | 'out_of_stock' | 'ineligible' | 'removed';
    status_before_ineligible: string | null;
    /** { kind: restriction|suspension|product|staff|fulfillment_service, id } */
    ineligible_source: Json | null;
    status_reason: Json | null;
    publish_on_approval: boolean;
    content_gaps: string[];
    terms_version: number;
    published_at: Date | null;
    removed_at: Date | null;
    created_at: Date;
    updated_at: Date;
  };
  /** Every price in force and when; basis for 'lowest price in the last 30 days' was-price checks */
  offer_price_history: {
    id: string;
    offer_id: string;
    price_amount: number;
    compare_at_amount: number | null;
    valid_from: Date;
    valid_to: Date | null;
    price_change_id: string | null;
    actor_kind: string;
    actor_id: string | null;
  };
  /** Requested, scheduled, approval-gated and applied price changes */
  price_changes: {
    id: string;
    offer_id: string;
    from_amount: number;
    to_amount: number;
    change_pct: string;
    compare_at_amount: number | null;
    compare_at_basis: string | null;
    starts_at: Date | null;
    ends_at: Date | null;
    revert_to_amount: number | null;
    reason: string | null;
    source: string;
    bulk_job_id: string | null;
    state: string;
    approval_request_id: string | null;
    requested_by_kind: string;
    requested_by_id: string | null;
    decided_at: Date | null;
    applied_at: Date | null;
    created_at: Date;
  };
  /** Every status change with reason and actor */
  offer_status_log: {
    id: string;
    offer_id: string;
    from_status: string | null;
    to_status: string;
    event: string;
    reason_code: string | null;
    reason: string | null;
    affected_activity: string | null;
    appeal_route: string | null;
    review_date: string | null;
    actor_kind: string;
    actor_id: string | null;
    at: Date;
  };
  /** Featured-offer eligibility per offer (location-independent part) */
  offer_eligibility: {
    offer_id: string;
    eligible: boolean;
    reasons: Json;
    seller_on_time_pct: string | null;
    seller_restriction_ref: string | null;
    evaluated_at: Date;
  };
  /** Cached featured-offer decision per variant, condition group and delivery zone */
  featured_offers: {
    variant_id: string;
    condition_group: 'new' | 'used' | 'refurbished';
    zone_key: string;
    product_id: string;
    offer_id: string | null;
    rule_version: number;
    candidates: Json;
    dirty: boolean;
    computed_at: Date;
  };
  /** Published versions of the featured-offer rule */
  featured_rules: {
    version: number;
    text: string;
    steps: Json;
    parameters: Json;
    effective_from: Date;
    reason: string;
    published_by: string;
    published_at: Date;
  };
  /** Uploaded price/quantity files (seller or Official Store) */
  bulk_update_jobs: {
    id: string;
    owner_type: string;
    seller_id: string | null;
    file_media_id: string;
    file_name: string;
    state: string;
    totals: Json;
    report_media_id: string | null;
    uploaded_by: string;
    uploaded_at: Date;
    applied_by: string | null;
    applied_at: Date | null;
    expires_at: Date;
    failure: string | null;
  };
  bulk_update_rows: {
    job_id: string;
    row_no: number;
    seller_sku: string;
    offer_id: string | null;
    price_from: number | null;
    price_to: number | null;
    qty_from: number | null;
    qty_to: number | null;
    result: string;
    error_code: string | null;
    error_message: string | null;
  };
}

